function generateBackgroundSpans(){const section=document.getElementById('section');if(!section)return;section.querySelectorAll('span.bg-span').forEach(span=>span.remove());const isDarkMode=localStorage.getItem('darkMode')!=='false';let cols=16;if(window.innerWidth<=600){cols=6;}else if(window.innerWidth<=900){cols=10;}
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){cols=2;}
const spanSize=window.innerWidth/cols;const rows=Math.ceil(window.innerHeight/spanSize)+4;const totalSpans=cols*rows;const fragment=document.createDocumentFragment();const signinForm=section.querySelector('.signin');for(let i=0;i<totalSpans;i++){const span=document.createElement('span');span.classList.add('bg-span');span.className+=' '+(isDarkMode?'green':'blue');fragment.appendChild(span);}
if(signinForm){section.insertBefore(fragment,signinForm);}else{section.appendChild(fragment);}}
function initBlogBase(){const isDarkMode=localStorage.getItem('darkMode')!=='false';document.body.classList.toggle("light",!isDarkMode);document.body.classList.toggle("dark",isDarkMode);document.body.classList.toggle('darkmode',isDarkMode);generateBackgroundSpans();document.querySelectorAll("section span.bg-span").forEach(x=>x.classList.toggle("green",isDarkMode));document.querySelectorAll("section span.bg-span").forEach(x=>x.classList.toggle("blue",!isDarkMode));const toggleCheckbox=document.getElementById("toggle");if(toggleCheckbox)toggleCheckbox.checked=isDarkMode;if(typeof applyDarkModeStyles==='function'){applyDarkModeStyles(isDarkMode);}
const togglePasswordBtn=document.getElementById("togglePassword");if(togglePasswordBtn){togglePasswordBtn.addEventListener("click",myFunction);}}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initBlogBase);}else{initBlogBase();}
window.addEventListener('resize',generateBackgroundSpans);function something(x){if(x.style.color=="black"){x.style.color="white";}else{x.style.color="black";}}
function some(y){y.classList.toggle("text-muted");if(y.style.color=="#FFC107"){y.style.color="";}else{y.style.color="#FFC107";}}
function darktheme(){document.body.classList.toggle("darkmode");document.querySelectorAll(".navbar-brand").forEach(something);document.querySelectorAll(".nav-link").forEach(something);document.querySelectorAll("p").forEach(some);document.querySelectorAll("span").forEach(some);document.querySelectorAll(".card-body").forEach(x=>x.classList.toggle('darkmode'));document.querySelectorAll("section span.bg-span").forEach(x=>x.classList.toggle("green"));document.querySelectorAll("section span.bg-span").forEach(x=>x.classList.toggle("blue"));const menuthingEl=document.getElementById("menuthing");if(menuthingEl){menuthingEl.classList.toggle("navbar-light");menuthingEl.classList.toggle("navbar-dark");}
const currentMode=document.body.classList.contains('darkmode');localStorage.setItem('darkMode',currentMode);}
function myFunction(e){if(e)e.preventDefault();var toggleBtn=document.getElementById("togglePassword");if(!toggleBtn)return;var container=toggleBtn.closest(".inputBox");if(!container)return;var x=container.querySelector("input[type='password'], input[type='text']");if(!x)return;if(x.type==="password"){x.type="text";toggleBtn.innerHTML='<i class="fa-solid fa-eye-slash toggle-password-icon" id="togglePasswordIcon"></i>';}else{x.type="password";toggleBtn.innerHTML='<i class="fa-solid fa-eye toggle-password-icon" id="togglePasswordIcon"></i>';}}
document.querySelectorAll('.inputBox input').forEach(input=>{input.addEventListener('input',function(){toggleSubmitButton();});});function toggleSubmitButton(){const username=document.querySelector('input[type="text"]');const password=document.getElementById('password');const submitButton=document.querySelector('input[type="submit"]');if(username&&password&&submitButton){if(username.value!==''&&password.value!==''){submitButton.classList.add('enabled');}else{submitButton.classList.remove('enabled');}}}
const submitBtn=document.querySelector('input[type="submit"]');if(submitBtn){submitBtn.addEventListener('click',function(event){const username=document.querySelector('input[type="text"]');const password=document.getElementById('password');if(username.value===''||password.value===''){alert('Please fill in both fields.');event.preventDefault();}});}
const hamburger=document.querySelector('.hamburger');const navMenu=document.querySelector('.nav-menu');if(hamburger&&navMenu){hamburger.addEventListener('click',()=>{navMenu.classList.toggle('active');hamburger.classList.toggle('active');});document.addEventListener('click',(e)=>{if(!hamburger.contains(e.target)&&!navMenu.contains(e.target)){navMenu.classList.remove('active');hamburger.classList.remove('active');}});};